// TestEnvInt covers the B5 int-env-parsing logic: an empty value uses the
// default; a valid value overrides; a malformed value falls back to the default
// + logs (INV-env-defaults: startup never aborts on an enrich knob). The parser
// does not clamp — a negative passes through; enrich.NewQueue's withDefaults
// re-applies the §4.4 default for a non-positive value, so the pool cannot be
// accidentally disabled. That clamp is enrich's concern, asserted in enrich
// tests; this test pins the parser's own contract.
func TestEnvInt(t *testing.T) {
	const key = "MELLIFERA_TEST_ENV_INT"
	const def = 4
	for _, tc := range []struct {
		name string
		val  string
		want int
	}{
		{"empty_uses_default", "", def},
		{"valid_override", "8", 8},
		{"malformed_falls_back", "not-an-int", def},
		{"negative_passes_through_unclamped", "-1", -1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Setenv(key, tc.val)
			if got := envInt(key, def); got != tc.want {
				t.Errorf("envInt(%q=%q, def=%d) = %d, want %d", key, tc.val, def, got, tc.want)
			}
		})
	}
}

// TestEnvDuration covers the B5 duration-env-parsing logic over the time units the
// §4.4 knobs use (seconds/minutes/hours/days), plus the empty + malformed
// fallbacks (INV-env-defaults).
func TestEnvDuration(t *testing.T) {
	const key = "MELLIFERA_TEST_ENV_DUR"
	def := 60 * time.Second
	for _, tc := range []struct {
		name string
		val  string
		want time.Duration
	}{
		{"empty_uses_default", "", def},
		{"valid_seconds", "90s", 90 * time.Second},
		{"valid_minutes", "5m", 5 * time.Minute},
		{"valid_hours", "12h", 12 * time.Hour},
		{"valid_days", "168h", 7 * 24 * time.Hour},
		{"malformed_falls_back", "soon", def},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Setenv(key, tc.val)
			if got := envDuration(key, def); got != tc.want {
				t.Errorf("envDuration(%q=%q, def=%v) = %v, want %v", key, tc.val, def, got, tc.want)
			}
		})
	}
}
